import { Group, Mesh, PlaneGeometry } from 'three';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, Color } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  const timelines = [];

  // 1. Stage / Backdrop Plane (~7x6 units at z=-2.5) with vertical gradient
  const bgGeom = new PlaneGeometry(7.5, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true });

  // Custom shader node vertical gradient using spec vertical gradient stops
  const vUv = uv();
  const bgGrad = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10
    vec3(0.066, 0.066, 0.09),  // #111117
    vUv.y
  );
  bgMat.colorNode = vec3(bgGrad);

  const backdrop = new Mesh(bgGeom, bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // 2. Ribbon Rail Configuration
  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;
  const railGeom = new PlaneGeometry(ribbonWidth, ribbonHeight);

  // Rail material: albedo #111117, roughness 0.6, metalness 0.2
  const railMat = new MeshStandardNodeMaterial({
    color: 0x111117,
    roughness: 0.6,
    metalness: 0.2
  });
  const railMesh = new Mesh(railGeom, railMat);
  group.add(railMesh);

  // Top/Bottom 0.006-unit hairlines in #23232b
  const hairlineGeom = new PlaneGeometry(ribbonWidth, 0.006);
  const hairlineMat = new MeshStandardNodeMaterial({ color: 0x23232b, roughness: 0.5 });

  const topHairline = new Mesh(hairlineGeom, hairlineMat);
  topHairline.position.set(0, ribbonHeight / 2 - 0.003, 0.002);
  railMesh.add(topHairline);

  const bottomHairline = new Mesh(hairlineGeom, hairlineMat);
  bottomHairline.position.set(0, -ribbonHeight / 2 + 0.003, 0.002);
  railMesh.add(bottomHairline);

  // 3. Local Lights to light the product-like shot
  const keyLight = new THREE.DirectionalLight('#ffffff', 1.2);
  keyLight.position.set(3, 4, 3);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-3, -2, 2);
  group.add(rimLight);

  const ambientFill = new THREE.AmbientLight('#111117', 0.5);
  group.add(ambientFill);

  // 4. Constructing the Ticker Items & Loop
  const textItems = config.textContent ?? (config.intent && config.intent.visualSpec && config.intent.visualSpec.textContent) ?? [];
  const entriesGroup = new Group();
  entriesGroup.position.z = 0.02; // Float 0.02 above rail
  railMesh.add(entriesGroup);

  const tickerElements = [];
  let currentX = 0;
  const baseSpacing = 0.5; // Gap of 0.5 units on both sides of ticks (2x base spacing unit)

  // Sub-generator for a single text block
  const createTextBlock = (textStr) => {
    return ctx.fontAtlas.createText(textStr, {
      fontSize: 13,
      color: '#e8ecf2', // paper tone
      align: 'left'
    });
  };

  // Sub-generator for the red vertical accent tick mark (0.02w x 0.14h, #ff2a38, emissive 1.5)
  const createTickMark = () => {
    const tickGeom = new PlaneGeometry(0.02, 0.14);
    const tickMat = new MeshStandardNodeMaterial({
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.5
    });
    return new Mesh(tickGeom, tickMat);
  };

  // We write out entries, keeping track of bounds
  textItems.forEach((item, index) => {
    // 1. Text Element
    const txtNode = createTextBlock(item.text);
    txtNode.position.set(currentX, -0.05, 0); // vertically centered
    entriesGroup.add(txtNode);
    tickerElements.push({ obj: txtNode, xOffset: currentX });

    // Crude character width estimation: base font width (unit-scale) about 0.075 per char
    const approxWidth = item.text.length * 0.082;
    currentX += approxWidth;

    // 2. Padding + Tick Mark + Padding
    currentX += baseSpacing;
    const tick = createTickMark();
    tick.position.set(currentX, 0, 0);
    entriesGroup.add(tick);
    tickerElements.push({ obj: tick, xOffset: currentX });
    currentX += baseSpacing;
  });

  const totalStripLength = currentX;

  // Duplicate for seamless infinite loop (wrapping over totalStripLength)
  textItems.forEach((item) => {
    const txtNode = createTextBlock(item.text);
    const targetX = currentX;
    txtNode.position.set(targetX, -0.05, 0);
    entriesGroup.add(txtNode);
    tickerElements.push({ obj: txtNode, xOffset: targetX });

    const approxWidth = item.text.length * 0.082;
    currentX += approxWidth;

    currentX += baseSpacing;
    const tick = createTickMark();
    tick.position.set(currentX, 0, 0);
    entriesGroup.add(tick);
    tickerElements.push({ obj: tick, xOffset: currentX });
    currentX += baseSpacing;
  });

  // Calculate loop period: linear timing, velocity 0.4 scene units/sec
  const velocity = 0.4;
  const loopDuration = totalStripLength / velocity;

  // Wrap timeline for continuous scrolling
  const scrollAnimObj = { x: 0 };
  const scrollTl = gsap.to(scrollAnimObj, {
    x: -totalStripLength,
    duration: loopDuration,
    ease: 'none',
    repeat: -1,
    onUpdate: () => {
      entriesGroup.position.x = scrollAnimObj.x;
    }
  });
  timelines.push(scrollTl);

  // 5. Edge Fade Masks
  // Dissolve edge fades via Fragment Shader magic directly on elements using Custom Node Flow
  // Edge fade masks 0.6 units wide at both ends using the stop ramp #0b0b10ff (at 0.0) -> #0b0b1000 (at 0.09) and mirrored
  const fadeWidth = 0.6;
  const halfRibbon = ribbonWidth / 2;

  // Apply visual-falloff alpha mask logic directly into material compilation for custom texts/ticks
  // Since FontAtlas returns materials that we can intercept, we set up post-processing or apply node attributes on children.
  entriesGroup.traverse((child) => {
    if (child.material) {
      const prevColorNode = child.material.colorNode || vec3(Color.fromHex(child.material.color || '#ffffff'));

      // Node position logic relative to rail boundary
      const localX = child.position;
      // We will perform procedural alpha fade using custom shader logic relative to world/parent X
      // But for total robustness across custom text materials, we override opacity
      child.material.transparent = true;
      child.material.opacity = 1.0;
    }
  });

  // Alternately, we overlay two gradient cover panels on both ends to hide the clipping seamlessly
  const maskGeom = new PlaneGeometry(fadeWidth, ribbonHeight + 0.02);

  // Left fade cover: #0b0b10ff to transparent
  const leftMaskMat = new MeshBasicNodeMaterial({ transparent: true });
  leftMaskMat.colorNode = vec3(0.043, 0.043, 0.063);
  leftMaskMat.opacityNode = mix(1.0, 0.0, uv().x);
  const leftMask = new Mesh(maskGeom, leftMaskMat);
  leftMask.position.set(-halfRibbon + fadeWidth / 2, 0, 0.05);
  railMesh.add(leftMask);

  // Right fade cover: transparent to #0b0b10ff
  const rightMaskMat = new MeshBasicNodeMaterial({ transparent: true });
  rightMaskMat.colorNode = vec3(0.043, 0.043, 0.063);
  rightMaskMat.opacityNode = mix(0.0, 1.0, uv().x);
  const rightMask = new Mesh(maskGeom, rightMaskMat);
  rightMask.position.set(halfRibbon - fadeWidth / 2, 0, 0.05);
  railMesh.add(rightMask);

  // Apply cinematic primitives (fly-through applied in background or as dynamic speed modifier)
  const primitivesCleanup = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const res = ctx.primitives[prim.name](railMesh, prim.params);
        if (res && res.cleanup) primitivesCleanup.push(res.cleanup);
        if (res && res.timeline) timelines.push(res.timeline);
      }
    });
  }

  // Cleanup handler
  group.userData = {
    cleanup() {
      timelines.forEach((tl) => tl.kill());
      primitivesCleanup.forEach((clean) => clean());
      bgGeom.dispose();
      bgMat.dispose();
      railGeom.dispose();
      railMat.dispose();
      hairlineGeom.dispose();
      hairlineMat.dispose();
      maskGeom.dispose();
      leftMaskMat.dispose();
      rightMaskMat.dispose();
    }
  };

  return group;
}
